INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-042', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 42 题', '一长为 1 m 的均匀直棒可绕过其一端且与棒垂直的水平光滑固定轴转动．抬起另一端使棒向上与水平面成 $60^{\circ}$ ，然后无初转速地将棒释放．已知棒对轴的转动惯量为 $\frac{1}{3}ml^{2}$ ，其中 m 和 l 分别为棒的质量和长度．求：

(1)放手时棒的角加速度；

(2)棒转到水平位置时的角加速度', '[]'::jsonb, '$\beta_0=\frac{3g}{4l}=7.35\,\mathrm{rad/s^2}$; $\beta=\frac{3g}{2l}=14.7\,\mathrm{rad/s^2}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$M=mg\frac{l}{2}\cos60^\circ=\frac{1}{4}mgl$，$\beta_0=M/J=\frac{3g}{4l}$。（2）水平位置 $M=\frac{1}{2}mgl$，$\beta=\frac{3g}{2l}$。', NULL, NULL, '/physics/q042.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-043', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 43 题', '两个大小不同、具有水平光滑轴的定滑轮，顶点在同一水平线上。小滑轮的质量为 m，半径为 r，对轴的转动惯量 $J=\frac{1}{2}m r^{2}$ 。大滑轮的质量 $m {''}{=}2 m$ ，半径 $r^{\prime}{=}2 r$ ，对轴的转动惯量 $J^{\prime}=\frac{1}{2}m^{\prime}{r^{\prime}}^{2}$ 。一根不可伸长的轻质细绳跨过这两个定滑轮，绳的两端分别挂着物体 A和 B。A的质量为 m，B的质量 $m {''}{=}2 m$ 。这一系统由静止开始转动。已知 $m {=}6.0 \mathrm{kg}$ ， $r {=}5.0 \mathrm{cm}$ 。求两滑轮的角加速度和它们之间绳中的张力。', '[]'::jsonb, '$\beta_A=\frac{4g}{17r}\approx46\,\mathrm{rad/s^2}$; $\beta_B=\frac{2g}{17r}\approx23\,\mathrm{rad/s^2}$; $T=\frac{12mg}{17}\approx41.3\,\mathrm{N}$', '[]'::jsonb, NULL, NULL, NULL, '设绳中张力为 $T$，A 向上加速度 $a$，B 向下加速度 $a$。对小滑轮：$(T-T_1)r=J\beta_A$；对大滑轮：$(T_2-T)r''=J''\beta_B$；物体：$T_1-mg=ma$，$2mg-T_2=2ma$；$a=r\beta_A=r''\beta_B$。联立解得。', NULL, NULL, '/physics/q043.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
